import { readFileSync, writeFileSync, mkdirSync, unlinkSync, existsSync } from 'node:fs';
import { dirname } from 'node:path';
import type { BridgeClient } from '@devpilot.sh/bridge-client';

/**
 * Closes the loop: a conductor run that finishes reports completion to the
 * bridge, which is what makes the hosted side write back to Linear.
 *
 * ## Why this exists separately from the handler
 *
 * The single-session path reports completion through the orchestrator's status
 * poller, which lives in the bridge process for exactly as long as the session
 * does. The planned path has no equivalent: the handler must RETURN at the
 * review gate (holding a queue claim while a human deliberates is invisible work
 * that the stale sweep re-runs), and the run then continues under the cockpit
 * for minutes or hours afterwards. So without something watching, a planned
 * ticket runs to completion and Linear is never told — the loop the user sees
 * simply stops.
 *
 * `POST /api/sessions/:id/complete` already calls `syncSessionCompletionToLinear`
 * hosted-side. This is the missing caller, not a new mechanism.
 *
 * ## Surviving a restart
 *
 * It used to hold runs in memory only, so a restarted bridge orphaned anything
 * in flight: the run kept going in the cockpit, and Linear was never told how it
 * ended. Observed on AVA-10 — the bridge was restarted to pick up a new CLI, the
 * session was never re-claimed, and the ticket was left showing an error for a
 * run that had not actually failed.
 *
 * The tracked set is now mirrored to disk. The bridge is the only party that
 * can do this: the hosted plane records the session but never learns the cockpit
 * item id, so it cannot reconstruct what to poll.
 *
 * Restored entries are treated as claims to verify, not as truth. A run whose
 * item the cockpit no longer knows about is dropped rather than polled forever,
 * because stale local state must not outlive the thing it describes.
 */

export interface ConductorState {
  status?: string;
  awaiting?: 'review' | 'wave' | null;
  completedWaves?: number[];
  errors?: string[];
  review?: {
    score?: { parallelizationScore?: number };
    plan?: {
      waves?: {
        label?: string;
        tasks?: {
          taskCode?: string;
          description?: string;
          filePaths?: string[];
          complexity?: string;
          recommendedModel?: string;
          canRunInParallel?: boolean;
        }[];
      }[];
      dependencyEdges?: { from: string; to: string; type?: string }[];
      criticalPath?: string[];
    };
  } | null;
  currentWaveIndex?: number;
  score?: { parallelizationScore?: number } | null;
  lastDispatch?: { dispatched?: number; queued?: number } | null;
  /** What the run has produced. See `outcomeFor` in the cockpit's conductor route. */
  outcome?: {
    tasksTotal?: number;
    tasksComplete?: number;
    tasksFailed?: number;
    wavesTotal?: number;
    filesChanged?: string[];
    costUsd?: number;
    failures?: { taskCode: string; error: string }[];
    /**
     * Why the plan is paused when nobody paused it — it was left executing and
     * had been idle too long to pick up when the cockpit restarted. Null, or
     * absent on an older cockpit, otherwise.
     */
    pausedReason?: string | null;
    /**
     * Where the run's work is. `summary` is one sentence naming the run branch
     * and saying it has not been pushed; it is the only part of this relayed
     * outward, and it carries a branch name and a short sha — nothing else.
     * Null, or absent, when nothing has been dispatched or the cockpit
     * predates per-task branches.
     */
    isolation?: {
      isolated?: boolean;
      summary?: string | null;
      reason?: string | null;
    } | null;
  } | null;
}

/**
 * One paragraph saying where a finished run's work is, or '' when the cockpit
 * did not say.
 *
 * "DevPilot finished 6 tasks" is the sentence after which a person asks "where
 * is it?", and until this was added the answer was nowhere in what Linear was
 * told. There are two answers and they are opposites: an isolated run leaves a
 * local branch and nothing in the operator's checkout; a run that could not be
 * isolated leaves uncommitted edits IN the checkout and no branch. Saying
 * neither would let a reader assume whichever they expected.
 */
function whereTheWorkIs(state: ConductorState): string {
  const isolation = state.outcome?.isolation;
  if (!isolation) return '';
  if (isolation.isolated) return isolation.summary ? `\n\n${isolation.summary}` : '';
  return (
    '\n\nThis run was not given a branch per task' +
    (isolation.reason ? ` (${isolation.reason})` : '') +
    ', so its changes are uncommitted edits in the checkout on the machine that ran it.'
  );
}

/**
 * A one-line description of where a run currently is, plus a signature used to
 * suppress repeats. Returns null when there is nothing worth saying.
 */
function progressReport(
  state: ConductorState,
  /** Cockpit base URL and item, so the message can be somewhere you can go. */
  links: { hosted: string; sessionId: string }
): { signature: string; message: string; percent: number } | null {
  if (state.awaiting === 'review') {
    const waves = state.review?.plan?.waves?.length ?? 0;
    const tasks =
      state.review?.plan?.waves?.reduce((n, w) => n + (w.tasks?.length ?? 0), 0) ?? 0;
    const pct = Math.round((state.score?.parallelizationScore ?? 0) * 100);
    return {
      signature: 'review',
      message:
        `Plan ready — ${waves} wave${waves === 1 ? '' : 's'}, ${tasks} task${tasks === 1 ? '' : 's'}, ` +
        `${pct}% parallel. ` +
        (links.hosted
          ? `[Review it in the cockpit](${links.hosted}/sessions/${links.sessionId}) to dispatch`
          : 'Review it in the cockpit to dispatch') +
        `, or reply here with constraints to re-plan. Awaiting review.`,
      percent: 40,
    };
  }

  /**
   * A plan the cockpit is holding. Said once, with the reason, because the
   * alternative is a ticket that reads "Wave 2 — 3/6 tasks done" for ever: the
   * run is not failing and not finishing, and only this says why. It is not
   * terminal — resuming it from the cockpit carries on — so it is reported as
   * progress and the run stays watched.
   */
  const pausedReason = state.outcome?.pausedReason;
  if (pausedReason) {
    const done = state.completedWaves?.length ?? 0;
    return {
      signature: `paused:${pausedReason}`,
      message: `Run paused — ${pausedReason}`,
      percent: Math.min(60 + done * 15, 95),
    };
  }

  if (state.status === 'executing') {
    const wave = state.currentWaveIndex ?? 0;
    const done = state.completedWaves?.length ?? 0;
    const d = state.lastDispatch?.dispatched ?? 0;
    const q = state.lastDispatch?.queued ?? 0;
    const o = state.outcome ?? {};

    /**
     * Progress that survives being read weeks later.
     *
     * "Dispatching wave 2" says the machinery moved. Adding tasks done, files
     * touched so far and spend says what it *cost* and what it *changed* — the
     * two questions anyone actually brings to a ticket. The signature includes
     * the task count so a wave that is quietly making progress still updates,
     * rather than going silent between dispatch boundaries.
     */
    const complete = o.tasksComplete ?? 0;
    const total = o.tasksTotal ?? 0;
    const files = o.filesChanged?.length ?? 0;
    const cost =
      typeof o.costUsd === 'number' && o.costUsd > 0 ? `, $${o.costUsd.toFixed(2)} so far` : '';

    const detail = total
      ? ` — ${complete}/${total} tasks done, ${files} file${files === 1 ? '' : 's'} touched${cost}`
      : d || q
        ? ` — ${d} agent${d === 1 ? '' : 's'} running, ${q} queued`
        : '';

    return {
      signature: `wave:${wave}:${done}:${complete}:${files}`,
      message:
        `Wave ${wave + 1}${total ? ` of ${o.wavesTotal ?? '?'}` : ''}${detail}` +
        (links.hosted
          ? `. [Watch the waves](${links.hosted}/sessions/${links.sessionId}).`
          : '.'),
      percent: Math.min(60 + done * 15, 95),
    };
  }

  return null;
}

export interface WatchedRun {
  /** Bridge session id — what completion is reported against. */
  sessionId: string;
  /** Cockpit horizon item whose conductor run this is. */
  itemId: string;
  linearIdentifier: string;
}

export interface ConductorWatcherOptions {
  client: BridgeClient;
  cockpitUrl: string;
  /**
   * File the tracked set is mirrored to. Omit to keep the old in-memory-only
   * behaviour, which is what the tests use unless they are testing persistence.
   */
  statePath?: string;
  /** How often to ask the cockpit for run state. Default 30s. */
  pollIntervalMs?: number;
  onLog?: (line: string) => void;
  /** Called for runs still unfinished when the watcher stops. */
  onLost?: (run: WatchedRun) => void;
  /** Injectable for tests. */
  fetchImpl?: typeof fetch;
}

const TERMINAL = new Set(['complete', 'failed']);

/** Files are listed, not just counted — the count is the least useful part. */
const MAX_LISTED_FILES = 12;

function successSummary(state: ConductorState): string {
  const o = state.outcome ?? {};
  const waves = o.wavesTotal ?? state.completedWaves?.length ?? 0;

  /**
   * Fall back to the plan's own task count when no outcome is available.
   *
   * An older cockpit does not return `outcome`, and reading a missing value as
   * zero made the summary say "finished 0 tasks" for a run that had just
   * completed successfully — asserting nothing was done when the truth is that
   * we do not know how much was.
   */
  const planned =
    state.review?.plan?.waves?.reduce((n, w) => n + (w.tasks?.length ?? 0), 0) ?? 0;
  const tasks = o.tasksComplete ?? planned;
  const files = o.filesChanged ?? [];

  const head =
    `DevPilot finished ${tasks} task${tasks === 1 ? '' : 's'} across ` +
    `${waves} wave${waves === 1 ? '' : 's'}` +
    (typeof o.costUsd === 'number' && o.costUsd > 0 ? ` for $${o.costUsd.toFixed(2)}` : '') +
    '.';

  if (files.length === 0) {
    // Only claim "nothing changed" when the cockpit actually told us. Absent
    // data and an empty result are different facts, and reporting the first as
    // the second would send a reviewer hunting a problem that may not exist.
    return (
      (o.filesChanged
        ? `${head}\n\n**No files were changed.** Worth checking whether the plan matched the intent.`
        : head) + whereTheWorkIs(state)
    );
  }

  const shown = files.slice(0, MAX_LISTED_FILES).map((f) => `- \`${f}\``);
  const more =
    files.length > MAX_LISTED_FILES
      ? `\n- …and ${files.length - MAX_LISTED_FILES} more`
      : '';

  return (
    `${head}\n\n**${files.length} file${files.length === 1 ? '' : 's'} changed**\n${shown.join('\n')}${more}` +
    whereTheWorkIs(state)
  );
}

function failureSummary(state: ConductorState): string {
  const o = state.outcome ?? {};
  const failures = o.failures ?? [];
  const last = state.errors?.[state.errors.length - 1];

  const head =
    `DevPilot run failed after ${o.tasksComplete ?? 0} of ${o.tasksTotal ?? 0} tasks` +
    (typeof o.costUsd === 'number' && o.costUsd > 0 ? ` ($${o.costUsd.toFixed(2)} spent)` : '') +
    '.';

  // Name the tasks that failed. "Run failed" sends someone to a log; a task
  // code and its error sends them to the problem.
  if (failures.length > 0) {
    const lines = failures.slice(0, 5).map((f) => `- **${f.taskCode}** — ${f.error}`);
    return `${head}\n\n**Failed tasks**\n${lines.join('\n')}` + whereTheWorkIs(state);
  }
  // A failed run still did work, and what completed before it failed is
  // somewhere: the same sentence applies.
  return (last ? `${head}\n\n${last}` : head) + whereTheWorkIs(state);
}

export class ConductorWatcher {
  private readonly runs = new Map<string, WatchedRun>();
  /** Last progress signature reported per session, so we do not repeat ourselves. */
  private readonly reported = new Map<string, string>();
  /** Sessions whose plan has already been mirrored, so we upload it once. */
  private readonly mirroredPlans = new Set<string>();
  private timer: NodeJS.Timeout | null = null;
  private readonly base: string;
  private readonly interval: number;
  private readonly log: (line: string) => void;
  private readonly doFetch: typeof fetch;

  constructor(private readonly opts: ConductorWatcherOptions) {
    this.base = opts.cockpitUrl.replace(/\/$/, '');
    this.interval = opts.pollIntervalMs ?? 30_000;
    this.log = opts.onLog ?? (() => {});
    this.doFetch = opts.fetchImpl ?? fetch;
  }

  /**
   * Begin watching a run. Idempotent per bridge session.
   *
   * `alreadyReported` seeds the dedup signature with something the caller has
   * just said. The dispatch handler announces the review gate itself, and
   * without this the watcher's first sweep announced it again — AVA-13 carried
   * two identical "Plan ready — 5 waves, 17 tasks, 71% parallel" activities
   * seconds apart, which reads as the agent stuttering rather than working.
   */
  watch(run: WatchedRun, alreadyReported?: 'review'): void {
    if (this.runs.has(run.sessionId)) return;
    this.runs.set(run.sessionId, run);
    if (alreadyReported) this.reported.set(run.sessionId, alreadyReported);
    this.persist();
    this.log(`watching ${run.linearIdentifier} (${this.runs.size} tracked)`);
    this.start();
  }

  /**
   * Re-adopt runs left behind by a previous process.
   *
   * Restored runs are claims, not facts — `check` verifies each against the
   * cockpit on the next sweep and drops any whose item has gone. Returns how
   * many were adopted so the caller can say so.
   */
  restore(): number {
    const path = this.opts.statePath;
    if (!path || !existsSync(path)) return 0;

    let entries: WatchedRun[] = [];
    try {
      const parsed: unknown = JSON.parse(readFileSync(path, 'utf8'));
      // A corrupt or hand-edited file must not stop the bridge from starting;
      // losing the watch list degrades write-back, refusing to boot loses
      // everything.
      if (Array.isArray(parsed)) {
        entries = parsed.filter(
          (e): e is WatchedRun =>
            Boolean(e) &&
            typeof (e as WatchedRun).sessionId === 'string' &&
            typeof (e as WatchedRun).itemId === 'string'
        );
      }
    } catch {
      return 0;
    }

    let adopted = 0;
    for (const run of entries) {
      if (this.runs.has(run.sessionId)) continue;
      this.runs.set(run.sessionId, run);
      adopted++;
    }
    if (adopted > 0) this.start();
    return adopted;
  }

  /**
   * Read this run's live telemetry from the cockpit and send it up.
   *
   * The cockpit knows what each agent is doing because the session runner
   * streams it there; the hosted plane knew none of it, so a session page could
   * only ever show a title and a percentage. Adopted sessions — Claude Code
   * sessions discovered already running — have no plan at all, which is why
   * twenty-eight of them displayed 0%: no denominator, and no activity either.
   */
  private async mirrorTelemetry(run: WatchedRun): Promise<void> {
    if (typeof this.opts.client.reportTelemetry !== 'function') return;

    try {
      const res = await this.doFetch(`${this.base}/api/fleet/state`);
      if (!res.ok) return;

      const state = (await res.json()) as {
        sessions?: {
          id: string;
          currentWorkstream?: string;
          telemetry?: {
            toolCalls?: number;
            writeCalls?: number;
            filesTouched?: string[];
            lastAction?: { tool: string; path?: string };
            commands?: string[];
            costUsd?: number;
            costIsEstimate?: boolean;
            tokensIn?: number;
            tokensOut?: number;
            tokensCacheRead?: number;
            tokensCacheWrite?: number;
            turns?: number;
            model?: string;
            harness?: string;
            elapsedMs?: number;
            idleMs?: number;
          } | null;
        }[];
      };

      // The cockpit keys sessions by its own id; this run's tasks may span
      // several. Aggregate them: the hosted view is per RUN, not per agent.
      const sessions = state.sessions ?? [];
      if (sessions.length === 0) return;

      const files = new Set<string>();
      let toolCalls = 0;
      let writeCalls = 0;
      let costUsd = 0;
      // Summed across the run's agents, like cost. These were tracked by every
      // session runner and dropped here, so a dispatched run reached the hosted
      // plane with its tokens blank.
      const tokens = { in: 0, out: 0, cacheRead: 0, cacheWrite: 0, turns: 0 };
      let sawTokens = false;
      // One run, one harness: the runner applies the same profile to every
      // agent it launches. Models can differ per task, so the run is named
      // for whichever did the most work.
      let harness: string | undefined;
      const modelTokens = new Map<string, number>();
      let estimated = false;
      let elapsedMs = 0;
      let idleMs = Number.MAX_SAFE_INTEGER;
      let action: string | undefined;

      for (const s of sessions) {
        const t = s.telemetry;
        if (!t) continue;
        toolCalls += t.toolCalls ?? 0;
        writeCalls += t.writeCalls ?? 0;
        costUsd += t.costUsd ?? 0;
        if (typeof t.tokensIn === 'number' || typeof t.tokensOut === 'number') sawTokens = true;
        tokens.in += t.tokensIn ?? 0;
        tokens.out += t.tokensOut ?? 0;
        tokens.cacheRead += t.tokensCacheRead ?? 0;
        tokens.cacheWrite += t.tokensCacheWrite ?? 0;
        tokens.turns += t.turns ?? 0;
        harness ??= t.harness;
        if (t.model) {
          const size =
            (t.tokensIn ?? 0) + (t.tokensOut ?? 0) + (t.tokensCacheRead ?? 0) + (t.tokensCacheWrite ?? 0);
          modelTokens.set(t.model, (modelTokens.get(t.model) ?? 0) + size);
        }
        estimated = estimated || Boolean(t.costIsEstimate);
        elapsedMs = Math.max(elapsedMs, t.elapsedMs ?? 0);
        // The LEAST idle agent decides: one busy agent means the run is not
        // stalled, however quiet the others are.
        idleMs = Math.min(idleMs, t.idleMs ?? Number.MAX_SAFE_INTEGER);
        for (const f of t.filesTouched ?? []) files.add(f);
        if (!action && t.lastAction) {
          const file = t.lastAction.path?.split('/').slice(-1)[0];
          action =
            t.lastAction.tool === 'Bash'
              ? programOf(t.commands?.at(-1))
              : `${t.lastAction.tool.toLowerCase()}${file ? ` ${file}` : ''}`;
        }
      }

      if (toolCalls === 0 && files.size === 0) return;

      await this.opts.client.reportTelemetry(run.sessionId, {
        toolCalls,
        writeCalls,
        filesTouched: [...files],
        currentAction: action,
        costUsd: costUsd > 0 ? costUsd : undefined,
        costEstimated: estimated,
        ...(sawTokens
          ? {
              tokensIn: tokens.in,
              tokensOut: tokens.out,
              tokensCacheRead: tokens.cacheRead,
              tokensCacheWrite: tokens.cacheWrite,
              turns: tokens.turns || undefined,
            }
          : {}),
        ...(harness ? { harness } : {}),
        ...(modelTokens.size > 0
          ? { model: [...modelTokens.entries()].sort((a, b) => b[1] - a[1])[0][0] }
          : {}),
        elapsedMs: elapsedMs || undefined,
        idleMs: idleMs === Number.MAX_SAFE_INTEGER ? undefined : idleMs,
      });
    } catch {
      // Never let an instrument frame disturb the run it describes.
    }
  }

  /** Mirror the tracked set to disk. Never throws — this is bookkeeping. */
  private persist(): void {
    const path = this.opts.statePath;
    if (!path) return;
    try {
      if (this.runs.size === 0) {
        if (existsSync(path)) unlinkSync(path);
        return;
      }
      mkdirSync(dirname(path), { recursive: true });
      writeFileSync(path, JSON.stringify([...this.runs.values()], null, 2), 'utf8');
    } catch {
      // A bridge that cannot write its watch list still works for this process.
    }
  }

  private start(): void {
    if (this.timer) return;
    this.timer = setInterval(() => void this.sweep(), this.interval);
    // Never hold the process open on this timer alone.
    this.timer.unref?.();
  }

  stop(): void {
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
    for (const run of this.runs.values()) this.opts.onLost?.(run);
    this.runs.clear();
  }

  /** Exposed for tests and for an immediate check after handing off a run. */
  async sweep(): Promise<void> {
    for (const run of [...this.runs.values()]) {
      try {
        await this.check(run);
      } catch (err) {
        // A cockpit that is down or restarting must not kill the watcher; the
        // next sweep retries. Losing the loop is worse than a noisy log.
        this.log(
          `${run.linearIdentifier}: state check failed (${
            err instanceof Error ? err.message : String(err)
          })`
        );
      }
    }
    if (this.runs.size === 0 && this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }

  private async check(run: WatchedRun): Promise<void> {
    const res = await this.doFetch(`${this.base}/api/items/${run.itemId}/conductor`);

    if (res.status === 404) {
      /**
       * The cockpit has no run for this item. For a restored entry that means
       * the item is gone — the database was reset, or the run was cleaned up
       * while this bridge was down. Polling it forever would keep a dead
       * session on the books and re-log the same failure every sweep.
       *
       * Drop it and say so. Reporting completion would be worse: we do not
       * know how it ended, and inventing an outcome for a Linear ticket is
       * exactly the kind of confident wrongness this write-back must not do.
       */
      this.runs.delete(run.sessionId);
      this.reported.delete(run.sessionId);
      this.persist();
      this.log(
        `${run.linearIdentifier}: no conductor run on the cockpit — dropped (was it reset?)`
      );
      return;
    }

    if (!res.ok) throw new Error(`conductor state → ${res.status}`);

    const state = (await res.json()) as ConductorState;

    if (!state.status || !TERMINAL.has(state.status)) {
      /**
       * Report progress while the run is still going.
       *
       * This used to return here, saying nothing until the run reached a
       * terminal state. A conductor run takes minutes to hours, so the Linear
       * agent session sat silent from the moment it was claimed — and Linear
       * marks an agent that stops emitting activities as unresponsive.
       * Observed on AVA-10: one "picking this up" thought, then thirty minutes
       * of nothing, then "Stopped responding" on the ticket while the planner
       * was working normally the whole time.
       *
       * The review gate matters most. The run is blocked on a human, and the
       * person who delegated the issue is reading the issue, not watching a
       * cockpit they may not know exists. Saying so there turns a dead-looking
       * session into a question they can answer.
       */
      /**
       * Mirror the plan from here as well as from the dispatch handler.
       *
       * The handler mirrors once, at claim time. If that call fails — the
       * hosted plane is unreachable, the cockpit restarts mid-plan, the bridge
       * is upgraded — nothing ever tried again, and the hosted cockpit stayed
       * empty for a run that has a perfectly good plan. Observed on AVA-12: the
       * cockpit was restarted during planning, the handler's call died with it,
       * and the plan existed everywhere except the place a hosted customer
       * would look.
       *
       * The watcher is already polling this exact state, so it is the natural
       * place to catch up. Once per session; best-effort, like the handler's.
       */
      if (
        state.review?.plan?.waves?.length &&
        !this.mirroredPlans.has(run.sessionId) &&
        typeof this.opts.client.mirrorSessionPlan === 'function'
      ) {
        const ok = await this.opts.client.mirrorSessionPlan(run.sessionId, {
          cockpitItemId: run.itemId,
          parallelization: state.review.score?.parallelizationScore,
          waves: state.review.plan.waves.map((w) => ({
            label: w.label,
            tasks: (w.tasks ?? []).map((t) => ({
              taskCode: t.taskCode ?? '',
              description: t.description ?? '',
              // The planner writes paths as markdown code spans.
              filePaths: (t.filePaths ?? []).map((f) => f.replace(/`/g, '').trim()),
              complexity: t.complexity,
              recommendedModel: t.recommendedModel,
              canRunInParallel: t.canRunInParallel,
            })),
          })),
          dependencyEdges: state.review.plan.dependencyEdges ?? [],
          criticalPath: state.review.plan.criticalPath ?? [],
        });
        if (ok) {
          this.mirroredPlans.add(run.sessionId);
          this.log(`${run.linearIdentifier}: plan mirrored to the hosted cockpit`);
        }
      }

      /**
       * Mirror the instruments, so the hosted cockpit shows work and not just
       * a title and a zero.
       *
       * Derived facts only — the assistant's prose and raw tool inputs are not
       * read here and have no column on the other side. Best-effort: an
       * instrument frame is never worth failing a run over.
       */
      void this.mirrorTelemetry(run);

      const progress = progressReport(state, {
        // Same guard as the handler: an older client has no `hostedUrl`, and a
        // missing link must never cost the progress report itself.
        hosted:
          typeof this.opts.client.hostedUrl === 'function' ? this.opts.client.hostedUrl() : '',
        sessionId: run.sessionId,
      });
      if (progress && this.reported.get(run.sessionId) !== progress.signature) {
        this.reported.set(run.sessionId, progress.signature);
        try {
          await this.opts.client.reportSessionStatus(run.sessionId, {
            status: 'running',
            progressPercent: progress.percent,
            message: progress.message,
          });
          this.log(`${run.linearIdentifier}: ${progress.message}`);
        } catch (err) {
          const reason = err instanceof Error ? err.message : String(err);

          /**
           * A missing session is permanent, not transient.
           *
           * Every `bridge connect` registers a NEW orchestrator, so a restart
           * leaves restored runs pointing at sessions the hosted plane now
           * considers owned by the previous identity — `requireOwnedSession`
           * correctly answers 404. Retrying that on every sweep never succeeds
           * and logs the same failure forever; observed on AVA-11 after several
           * restarts, once per poll indefinitely.
           *
           * Drop it, and say why. We deliberately do NOT report completion: we
           * do not know how the run ended, and inventing an outcome for a
           * Linear ticket is worse than admitting we lost track of it.
           */
          if (/not_found|not found/i.test(reason)) {
            this.runs.delete(run.sessionId);
            this.reported.delete(run.sessionId);
            this.persist();
            this.log(
              `${run.linearIdentifier}: session no longer reachable from this bridge — stopped watching`
            );
            return;
          }

          // Anything else may be transient. Never let a failed narration drop a
          // run whose completion is still owed.
          this.reported.delete(run.sessionId);
          this.log(`${run.linearIdentifier}: progress report failed (${reason})`);
        }
      }
      return;
    }

    const success = state.status === 'complete';
    const waves = state.completedWaves?.length ?? 0;
    const tasks =
      state.review?.plan?.waves?.reduce((n, w) => n + (w.tasks?.length ?? 0), 0) ?? 0;

    /**
     * A summary someone can act on.
     *
     * This used to say "DevPilot completed 2 waves" and nothing else. Linear is
     * the source of record, and the record was that something happened — no
     * files, no cost, no way to tell a run that wrote nine files from one that
     * wrote none. Everything below already existed; it was simply never joined
     * and never sent.
     */
    const summary = success ? successSummary(state) : failureSummary(state);

    // Remove BEFORE reporting: if the report throws, the run is not re-reported
    // on the next sweep. Linear comments are not idempotent, and a flapping
    // cockpit would otherwise post the same comment repeatedly.
    this.runs.delete(run.sessionId);
    this.reported.delete(run.sessionId);
    this.mirroredPlans.delete(run.sessionId);
    this.persist();

    await this.opts.client.reportSessionComplete(run.sessionId, {
      success,
      summary,
      ...(success ? {} : { errorMessage: summary }),
    });

    this.log(`${run.linearIdentifier}: reported ${success ? 'complete' : 'failed'} to the bridge`);
  }

  /**
   * The cockpit item a session's run belongs to, if this bridge is tracking it.
   *
   * The command applier needs this: a decision arrives addressed to a bridge
   * session, and the conductor is addressed by horizon item.
   */
  itemFor(sessionId: string): string | undefined {
    return this.runs.get(sessionId)?.itemId;
  }

  /** Test/introspection helper. */
  get tracked(): number {
    return this.runs.size;
  }
}

/**
 * The program a shell command runs, and nothing after it.
 *
 * This sent the first three words of the command, which reads fine for
 * `pnpm vitest run` and is a leak for `export STRIPE_KEY=sk_live_… &&` or
 * `curl -H 'Authorization: Bearer …'`. A command's arguments are tool input,
 * and tool input does not cross: the line the cockpit shows only needs to say
 * what kind of thing is running.
 *
 * Leading `VAR=value` assignments are skipped rather than shown, for the same
 * reason — they are where a secret on a command line usually sits.
 */
export function programOf(command: string | undefined): string {
  const words = (command ?? '').trim().split(/\s+/).filter(Boolean);
  // Skip assignments, the keywords that introduce them, and shell operators
  // (`&&`, `;`), then take the first word that could be a program at all.
  const program = words.find(
    (w) =>
      !/^[A-Za-z_][A-Za-z0-9_]*=/.test(w) &&
      w !== 'export' &&
      w !== 'env' &&
      /^[\w.@+/-]+$/.test(w),
  );
  if (!program) return 'shell';
  // A path to a binary is shown by its name; the directory is the machine's.
  const name = program.split('/').pop() ?? program;
  return /^[\w.@+-]{1,40}$/.test(name) ? name : 'shell';
}
